 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.createXMLHttpRequest = function () {
    /* sdd-asis-lifecycle:begin createXMLHttpRequest — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let xmlHttp = null;
    if (XMLHttpRequest) {
        xmlHttp = new XMLHttpRequest();
    }
    return xmlHttp;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getReason
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.getReason = async function (obj) {
    /* sdd-asis-lifecycle:begin getReason — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const idx = obj.getSelectedIndex();
    const classCd = obj[idx].value;
    if (classCd === "") {
        $c.util.getComponent('slc_reasonCd').removeAll();
        $c.util.getComponent('slc_reasonCd').options.add(new Option('전체', ''));
        return;
    }
    await scwin.tx_getReason_rawxhr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.handleStateChange
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.handleStateChange = function () {
    /* sdd-asis-lifecycle:begin handleStateChange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (scwin.xmlHttp.readyState == 4) {
        if (scwin.xmlHttp.status == 200) {
            scwin.updateSelectBox();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.updateSelectBox
 * @author Inswave
