scwin.updateSelectBox = function () {
    /* sdd-asis-lifecycle:begin updateSelectBox — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj = $c.util.getComponent('slc_reasonCd');
    const responseXML = scwin.xmlHttp.responseXML;
    scwin.clearSelectBox(obj);
    scwin.updateList(obj, responseXML);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.updateList
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj element
 * @returns
 * @hidden N
*/
scwin.updateList = function (obj, element) {
    /* sdd-asis-lifecycle:begin updateList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const nodeList = element.getElementsByTagName("item");
    let node = null;
    let name = null;
    let value = null;
    var i = 0;
    if (i < nodeList.length) {
        obj.options[0] = new Option('전체', '');
    }
    for (var i = 0; i < nodeList.length; i++) {
        node = nodeList[i];
        name = node.getElementsByTagName("name")[0].firstChild.nodeValue;
        value = node.getElementsByTagName("value")[0].firstChild.nodeValue;
        obj.options[i+1] = new Option(value, name);
    }
    scwin.delErrTrdRlf();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.clearSelectBox
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.clearSelectBox = function (obj) {
    /* sdd-asis-lifecycle:begin clearSelectBox — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 0; i < obj.options.length; i++) {
        obj.options[i] = null;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
