    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
