*/
scwin.fnSearch = function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const searchForm = $('#searchForm');
    $c.util.getComponent("ipt_reportName").setValue(encodeURI(document.searchForm.find('input:text[name=ipt_reportNameTmp]').val()));
    document.searchForm.ajaxSubmit({ ajaxUrl: '/common/reportname.do', ajaxCallBack: scwin.fnSearchCallBack });
    /* sdd-asis-lifecycle:end */
};


/**
